var companyDropDown=document.getElementById("companyDropDown");companyDropDown&&$("#companyDropDown")&&$("#company").on("change",function(o){o.preventDefault();var e=$("#company").val();$.ajax({type:"GET",url:"/api/warehouse/list/?company_id="+e,dataType:"json",success:function(o){$("#warehouseBox").show(),$("#warehouse").empty(),$("#warehouse").append(new Option("Select warehouse","")),o.warehouseData.forEach(function(o){$("#warehouse").append(new Option(o.name,o.id))})},error:function(o){console.log("Error : ",o)}})});